[BODY] CART_1.cart.line_items has exactly 1 line {BL} -- and exactly the line this case composed, nothing carried over
[BODY] CART_1.cart.line_items[product_id=P1_ID].quantity = 2 {BL}
[BODY] CART_1.cart.line_items[product_id=P1_ID].unit_price.amount = P1_PRICE {BL} -- the line carries the unit price search_products advertised for it
[BODY] CART_1.cart.line_items[product_id=P1_ID].line_total.amount = P1_PRICE * 2 {BL} -- line_total is unit_price x quantity, not a separately-sourced number
[BODY] CART_1.cart.totals.subtotal.amount = P1_PRICE * 2 {BL} -- the subtotal is the one composed line (the cart having been emptied first); tax-independent, so it holds on a taxed env (vcptcore-regression, 20%) and a tax-free one (vcst) alike
[BODY] CART_1.cart.totals.total.amount = subtotal.amount + tax_total.amount + shipping_total.amount + payment_total.amount + fee_total.amount - discount_total.amount, all read from CART_1.cart.totals {BL} -- the total is exactly the sum of its own breakdown (BL-CHK-006: total is tax-inclusive). Exact, not a floor: an amount added to or dropped from the total with the line itself correct fails here. UCP cart totals carry subtotal, tax_total, discount_total, shipping_total, payment_total, fee_total (observed on UCP 3.1010.0, 2026-10-13)
[BODY] CO_1.checkout.cart.totals.total.amount = CART_TOTAL {BL} -- the checkout snapshot must not drift from the cart it snapshots (delegated BL-CART-002/BL-CHK-001). NOTE the path: create_checkout WRAPS the cart, so the totals are at checkout.cart.totals, not checkout.totals — the earlier form of this case asserted checkout.totals.total.amount and read undefined
[BODY] CO_1.checkout.cart_id = CART_ID {OBSERVED} -- and it snapshots the cart this case actually composed

